body {
    font-family: sans-serif;
    display: flex;
    justify-content: center;
    padding: 2rem;
    background-color: #f4f4f9;
}

#app {
    width: 100%;
    max-width: 600px;
    background: white;
    padding: 2rem;
    border-radius: 8px;
    box-shadow: 0 4px 6px rgba(0,0,0,0.1);
}

h1 {
    text-align: center;
}

.message-list {
    height: 400px;
    overflow-y: auto;
    border: 1px solid #eee;
    margin-bottom: 1rem;
    padding: 1rem;
    display: flex;
    flex-direction: column;
    gap: 0.5rem;
}

.message {
    padding: 0.5rem 1rem;
    border-radius: 4px;
    background-color: #e7f3ff;
    align-self: flex-start;
}

.message .timestamp {
    font-size: 0.7rem;
    color: #666;
    display: block;
}

#message-form {
    display: flex;
    gap: 0.5rem;
}

#message-input {
    flex-grow: 1;
    padding: 0.5rem;
    border: 1px solid #ccc;
    border-radius: 4px;
}

button {
    padding: 0.5rem 1rem;
    background-color: #007bff;
    color: white;
    border: none;
    border-radius: 4px;
    cursor: pointer;
}

button:hover {
    background-color: #0056b3;
}

