    flex-direction: column;
    gap: 0.5rem;
}

.message {
    padding: 0.5rem 1rem;
    border-radius: 4px;
    background-color: #e7f3ff;
    align-self: flex-start;
}

.message .timestamp {
    font-size: 0.7rem;
    color: #666;
    display: block;
