    overflow-y: auto;
    border: 1px solid #eee;
    margin-bottom: 1rem;
    padding: 1rem;
    display: flex;
    flex-direction: column;
    gap: 0.5rem;
}

.message {
    padding: 0.5rem 1rem;
    border-radius: 4px;
    background-color: #e7f3ff;
    align-self: flex-start;
}

.message .timestamp {
    font-size: 0.7rem;
    color: #666;
    display: block;
}

#message-form {
    display: flex;
    gap: 0.5rem;
}

#message-input {
    flex-grow: 1;
    padding: 0.5rem;
    border: 1px solid #ccc;
    border-radius: 4px;
}

button {
    padding: 0.5rem 1rem;
    background-color: #007bff;
    color: white;
    border: none;
    border-radius: 4px;
    cursor: pointer;
}

button:hover {
    background-color: #0056b3;
}
