{"content": "body {
    font-family: sans-serif;
    display: flex;
    justify-content: center;
    padding: 2rem;
    background-color: #f4f4f9;
}

#app {
    width: 100%;
    max-width: 600px;
    background: white;
    padding: 2rem;
    border-radius: 8px;
    box-shadow: 0 4px 6px rgba(0,0,0,0.1);
}

h1 {
    text-align: center;
}

.message-list {
    height: 400px;
    overflow-y: auto;
    border: 1px solid #eee;
    margin-bottom: 1rem;
    padding: 1rem;
    display: flex;
    flex-direction: column;
    gap: 0.5rem;
}

.message {
